function timeToReachAll(n: number, links: number[][], start: number): number {
  const time = new Array(n + 1).fill(Infinity);
  time[start] = 0;
  for (let round = 1; round < n; round++) {
    let changed = false;
    for (const [u, v, w] of links) {
      if (time[u] + w < time[v]) { time[v] = time[u] + w; changed = true; }
    }
    if (!changed) break;
  }
  let last = 0;
  for (let i = 1; i <= n; i++) last = Math.max(last, time[i]);
  return last === Infinity ? -1 : last;
}

