class Heap<T> {
  private a: T[] = [];
  constructor(private before: (x: T, y: T) => boolean) {}
  get size(): number { return this.a.length; }
  push(x: T): void {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.before(a[i], a[p])) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop(): T {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && this.before(a[l], a[m])) m = l;
        if (r < a.length && this.before(a[r], a[m])) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function timeToReachAll(n: number, links: number[][], start: number): number {
  const adj: number[][][] = Array.from({ length: n + 1 }, () => []);
  for (const [u, v, w] of links) adj[u].push([v, w]);
  const time = new Array(n + 1).fill(Infinity);
  time[start] = 0;
  const heap = new Heap<number[]>((x, y) => x[0] < y[0]);
  heap.push([0, start]);
  let settled = 0, last = 0;
  while (heap.size) {
    const [t, u] = heap.pop();
    if (t > time[u]) continue; // stale: u was already settled with a smaller time
    settled++;
    last = t;
    for (const [v, w] of adj[u]) {
      if (t + w < time[v]) {
        time[v] = t + w;
        heap.push([time[v], v]);
      }
    }
  }
  return settled === n ? last : -1;
}

